import { HERO_IDS } from '../../../src/content/constants';
import { progressHero, projectProgression } from '../../../src/domain/progression';
import Phaser from 'phaser';
import '../../../src/style.css';
import { abilityCatalog,abilitySession } from '../../helpers/abilityCatalog';
import type { HeroId } from '../../../src/content/types';
import { BattleSession } from '../../../src/app/BattleSession';
import { BattleScene,type RunBattleHost } from '../../../src/phaser/BattleScene';
import { BattleDialogs } from '../../../src/ui/dialogs';
import { mountBattleLayout } from '../../../src/ui/battleLayout';
const hero=(new URLSearchParams(location.search).get('hero')??'mage') as HeroId;
const xp=new URLSearchParams(location.search).get('xp'),base=abilityCatalog(xp===null?undefined:2);
const party=HERO_IDS.map(id=>progressHero(id,Number(xp??0),1,base));
const projected=projectProgression(party,base);
// The default picker fixture deliberately authors two missiles; XP fixtures use canonical caster progression.
const catalog=xp===null?{...projected,abilities:{...projected.abilities,'ability:zz_mage':base.abilities['ability:zz_mage']}}:projected;
const saveKey=`ability-fixture-${hero}${xp===null?'':`-xp-${xp}`}`;
const saved=localStorage.getItem(saveKey);
const accepted=(state:import('../../../src/domain/types').BattleState)=>localStorage.setItem(saveKey,JSON.stringify(state));
const resumed=saved?BattleSession.fromSnapshot(catalog,JSON.parse(saved),accepted):null;
const initial=abilitySession(hero,catalog).state;
const injured=new URLSearchParams(location.search).has('injured');
const session=resumed?.ok?resumed.session:new BattleSession(catalog,injured?{...initial,units:initial.units.map(u=>u.defId==='fighter'?{...u,hp:u.hp-10}:u)}:initial,2,accepted,true);
session.progression=party;
const host:RunBattleHost={catalog,session,sound:{enabled:false},modalTransition:()=>{},ended:()=>{},restart:()=>location.reload(),dialogs:null!};
host.dialogs=new BattleDialogs(()=>host.modalTransition(),host.restart);
document.querySelector<HTMLElement>('#battle-controls')!.hidden=false;
document.querySelectorAll<HTMLElement>('#fit-panel > details').forEach(e=>e.hidden=true);
mountBattleLayout();
const scene=new BattleScene(()=>{},message=>{throw Error(message);},host);
new Phaser.Game({type:Phaser.AUTO,parent:'game',backgroundColor:'#172033',scale:{mode:Phaser.Scale.RESIZE,width:innerWidth,height:innerHeight},scene});
